  'error.reading-failed': { en: '{name} could not read this document yet. It tries again by itself: you have nothing to do.', fr: '{name} n’a pas encore pu lire ce document. Il réessaie de lui-même : vous n’avez rien à faire.', es: '{name} aún no ha podido leer este documento. Lo reintenta por sí solo: no tiene que hacer nada.', it: '{name} non ha ancora potuto leggere questo documento. Un nuovo tentativo parte automaticamente: lei non deve fare nulla.', 'pt-BR': '{name} ainda não conseguiu ler este documento. A leitura será tentada novamente de forma automática: você não precisa fazer nada.' },
