  // notices
  'notice.no-result-found': { en: '{name} found no result it could read in this document. Nothing is proposed.', fr: '{name} n’a trouvé aucun résultat lisible dans ce document. Rien n’est proposé.', es: '{name} no ha encontrado ningún resultado legible en este documento. No se propone nada.', it: '{name} non ha trovato in questo documento alcun risultato leggibile. Non viene proposto nulla.', 'pt-BR': '{name} não encontrou nenhum resultado legível neste documento. Nada é proposto.' },
  'notice.several-sampling-dates': { en: 'This document prints results for several sampling days, one column per day. {name} cannot yet tell which value was taken on which day, so it proposes nothing from it.', fr: 'Ce document imprime des résultats de plusieurs jours de prélèvement, une colonne par jour. {name} ne sait pas encore quelle valeur a été prise quel jour : il n’en propose donc rien.', es: 'Este documento imprime resultados de varios días de toma de muestras, una columna por día. {name} aún no sabe qué valor se tomó cada día, así que no propone nada a partir de él.', it: 'Questo documento riporta risultati di più giorni di prelievo, una colonna per giorno. {name} non sa ancora dire quale valore è stato rilevato in quale giorno, quindi non ne propone nessuno.', 'pt-BR': 'Este documento traz resultados de vários dias de coleta, uma coluna por dia. {name} ainda não sabe dizer qual valor foi coletado em qual dia, então não propõe nada a partir dele.' },
